output_text:
[
  {
    "id": "take_cart_at_entrance",
    "text": "Customers are obliged to take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "return_cart_to_top_left",
    "text": "Anyone who takes a cart is obliged to return it to the top-left cart-return point before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_point": "at(0,1)",
        "cart_parked_at_return_point": "cartAt(0,1)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_cart": {
          "pre": "PICKUP_CART",
          "post": "has_shopping_cart"
        },
        "return_cart_top_left": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "cart_return_point",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_point"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_cart",
      "discharge": "return_cart_top_left"
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "Customers are prohibited from exiting unless the cart has already been parked at the top-left return point.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "cart_drop_only_at_return",
    "text": "Leaving a cart is only permitted at the designated top-left cart-return cell.",
    "abstraction": {
      "state_properties": {
        "cart_return_cell": "at(0,1)",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "leave_cart_anywhere": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "LEAVE_CART"
            ]
          },
          "post": null
        },
        "leave_cart_outside_return_cell": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "LEAVE_CART",
              {
                "not": "cart_return_cell"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return_cell"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "Shelf items may not be picked up unless the customer is currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "has_shopping_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cart_based_item_pickup": {
          "pre": {
            "and": [
              "has_shopping_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        },
        "hand_based_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_based_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying merchandise by hand rather than in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_item_into_hands": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "has_shopping_cart"
              }
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_item_into_hands"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After the cart is parked at the return point, no further interactions with carts or shelves are permitted before exit.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "pickup_only_at_item_faces",
    "text": "Item pickup interactions are only permitted at recognized shelf-facing item access cells.",
    "abstraction": {
      "state_properties": {
        "apple_access_cell": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_access_cell": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_access_cell": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_access_cell": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "recognized_item_access_cell": {
          "or": [
            "apple_access_cell",
            "bread_access_cell",
            "milk_access_cell",
            "eggs_access_cell"
          ]
        }
      },
      "events": {
        "recognized_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "recognized_item_access_cell"
            ]
          },
          "post": null
        },
        "unrecognized_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "recognized_item_access_cell"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "unrecognized_item_pickup"
    }
  }
]
